// Normalizar sin confiar en el contenido.
const MAX_CHARS = 60000;
const form = $('Subir reporte').first();
let textoOriginal = String($input.first().json.text || '');
if (!textoOriginal.trim()) throw new Error('El PDF no tiene texto extraíble (¿es una imagen escaneada? requiere OCR).');
let texto = textoOriginal.replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const truncado = texto.length > MAX_CHARS;
if (truncado) texto = texto.slice(0, MAX_CHARS);
const cvesDetectados = [...new Set((texto.match(/CVE-\d{4}-\d{4,7}/gi) || []).map(c => c.toUpperCase()))];
return [{json:{reporte:texto, reporteOriginal:textoOriginal, contexto:String(form.json['Contexto']||'').trim()||'Sin contexto adicional.', archivo:form.binary?.Reporte?.fileName||'reporte.pdf', cvesDetectados, truncado}}];

