// Combina los datos determinísticos con el plan propuesto por el LLM.
// El plan es consultivo: este nodo no ejecuta remediaciones.
const base = $('Enriquecer y priorizar').first().json;
const raw = $input.first().json.output || {};
const incoming = Array.isArray(raw.planes) ? raw.planes : [];
const byId = new Map(incoming.filter(p => p && p.id).map(p => [String(p.id), p]));
const avisos = [];
const plan_remediacion = base.hallazgos.map(h => {
  const p = byId.get(h.id);
  if (!p) {
    avisos.push(`No se recibió un plan estructurado para ${h.id}; se generó una recomendación conservadora.`);
  }
  const fallbackAction = h.remediacion_reportada
    ? String(h.remediacion_reportada)
    : 'Consultar la documentación oficial del fabricante para identificar la corrección aplicable al producto y versión afectados.';
  const acciones = Array.isArray(p?.acciones) && p.acciones.length
    ? p.acciones.map(x => String(x))
    : [fallbackAction, 'Probar la corrección en un entorno controlado cuando sea posible.', 'Registrar el cambio y verificar nuevamente el hallazgo.'];
  const faltantes = Array.isArray(p?.datos_faltantes) ? p.datos_faltantes.map(String) : [];
  if (!h.activos.length) faltantes.push('No se identificaron activos concretos para este hallazgo.');
  if (!h.cves.length && !h.evidencia) faltantes.push('No hay CVE ni evidencia técnica suficiente para precisar la corrección.');
  const sospechoso = !!base.seguridad_documental?.sospechoso;
  const requiere_aprobacion = sospechoso || faltantes.length > 0 || p?.requiere_aprobacion === true || p?.confianza === 'baja';
  if (sospechoso) avisos.push(`El plan de ${h.id} queda marcado para aprobación por señales de seguridad documental.`);
  return {
    id: h.id,
    objetivo: String(p?.objetivo || `Reducir el riesgo asociado a ${h.nombre}.`),
    acciones,
    prerequisitos: Array.isArray(p?.prerequisitos) ? p.prerequisitos.map(String) : ['Confirmar producto, versión y alcance del activo antes de aplicar cambios.'],
    validacion: Array.isArray(p?.validacion) && p.validacion.length ? p.validacion.map(String) : ['Ejecutar nuevamente una comprobación autorizada para confirmar que el hallazgo ya no está presente.'],
    reversion: String(p?.reversion || 'Definir el procedimiento de reversión según la plataforma y el cambio antes de aplicarlo.'),
    riesgos_del_cambio: Array.isArray(p?.riesgos_del_cambio) ? p.riesgos_del_cambio.map(String) : ['La corrección podría afectar la disponibilidad o compatibilidad; evaluar en entorno controlado.'],
    datos_faltantes: [...new Set(faltantes)],
    confianza: ['alta','media','baja'].includes(p?.confianza) ? p.confianza : 'baja',
    requiere_aprobacion,
    estado: 'Propuesto; no ejecutado'
  };
});
return [{json:{...base, plan_remediacion, advertencias_plan_remediacion:[...new Set(avisos)]}}];
